"use strict";(self["webpackChunkejsoft"]=self["webpackChunkejsoft"]||[]).push([[697],{2697:function(e,a,n){n.d(a,{p:function(){return i},v:function(){return t}});var o=JSON.parse('{"0.3.25":{"ja":["Windows: TabDeck が Microsoft Store で公開されました — パネルと Android アプリの Windows ボタンからストアを開けます。","Linux: TabDeck に必要なパッケージ（xdotool、ydotool、wl-clipboard、xdg-utils）がない場合、起動時にインストールするか確認し、管理者パスワードを入力するとすぐにインストールします。X11・Wayland のどちらにも対応し、apt・dnf・zypper・pacman をサポートします。","Linux: 「後で」を選んだ場合も、トレイメニューの「必要なパッケージをインストール…」からいつでもインストールできます。インストール後は TabDeck が再接続され、「xdotool がありません」などの警告が消えます。","Android: Bluetooth で接続した機器がないのに、スマートフォン名の機器がパネルに追加される問題を修正しました。","Android（Google Play）: 「サブスクリプションの管理・解約」ボタンに長い説明文が表示される問題と、Android 15 以降で画面の上下がステータスバー・ナビゲーションバーに隠れる問題を修正しました。","iPhone・iPad（App Store）: アプリ内に設定画面を追加しました（表示、触覚の強さ、画面を消灯しない、サブスクリプション・購入と復元、情報）。パネルは iOS で選んだ言語（9 言語）に従います。"],"zh-cn":["Windows： TabDeck 已上架 Microsoft Store — 面板和 Android 应用中的 Windows 按钮会打开商店页面。","Linux： 如果缺少 TabDeck 需要的软件包（xdotool、ydotool、wl-clipboard、xdg-utils），启动时会询问是否安装，输入管理员密码后立即安装。X11 和 Wayland 均适用，支持 apt、dnf、zypper、pacman。","Linux： 如果选择了“稍后”，可随时通过托盘菜单中的“安装所需软件包…”进行安装。安装完成后 TabDeck 会重新连接，“缺少 xdotool”等警告将消失。","Android： 修复在没有通过蓝牙连接设备时，面板仍会添加以手机名称命名的设备的问题。","Android（Google Play）： 修复“管理或取消订阅”按钮显示长段说明的问题，以及在 Android 15 及以上版本中屏幕顶部和底部被状态栏、导航栏遮挡的问题。","iPhone 和 iPad（App Store）： 新增应用内设置页面（显示、触感强度、保持屏幕常亮、订阅与购买及恢复、关于）。面板跟随 iOS 中选择的语言（9 种语言）。"],"zh-tw":["Windows： TabDeck 已在 Microsoft Store 上架 — 面板和 Android App 中的 Windows 按鈕會開啟商店頁面。","Linux： 若缺少 TabDeck 需要的套件（xdotool、ydotool、wl-clipboard、xdg-utils），啟動時會詢問是否安裝，輸入管理員密碼後立即安裝。X11 與 Wayland 皆適用，支援 apt、dnf、zypper、pacman。","Linux： 若選擇了「稍後」，可隨時從系統匣選單的「安裝所需套件…」進行安裝。安裝完成後 TabDeck 會重新連線，「缺少 xdotool」等警告會消失。","Android： 修正沒有透過藍牙連線裝置時，面板仍會新增以手機名稱命名之裝置的問題。","Android（Google Play）： 修正「管理或取消訂閱」按鈕顯示長段說明的問題，以及在 Android 15 以上版本中畫面上下被狀態列、導覽列遮住的問題。","iPhone 與 iPad（App Store）： 新增 App 內設定畫面（顯示、觸覺強度、螢幕保持開啟、訂閱與購買及回復、關於）。面板會跟隨 iOS 中選擇的語言（9 種語言）。"],"de":["Windows: TabDeck ist jetzt im Microsoft Store — die Windows-Schaltfläche im Panel und in der Android-App öffnet ihn.","Linux: Fehlen Pakete, die TabDeck braucht (xdotool, ydotool, wl-clipboard, xdg-utils), bietet TabDeck beim Start an, sie zu installieren; nach Eingabe des Administratorpassworts werden sie installiert. Das funktioniert unter X11 und Wayland mit apt, dnf, zypper und pacman.","Linux: Wenn Sie „Später“ gewählt haben, können Sie jederzeit über „Benötigte Pakete installieren…“ im Infobereich-Menü installieren. Danach verbindet sich TabDeck neu, und Warnungen wie „xdotool fehlt“ verschwinden.","Android: Behoben: Das Panel fügte ein Gerät mit dem Namen des Telefons hinzu, obwohl kein Bluetooth-Gerät verbunden war.","Android (Google Play): Behoben: Die Schaltfläche „Abo verwalten oder kündigen“ zeigte einen langen Satz, und unter Android 15 und neuer wurden oberer und unterer Bildschirmrand von Status- und Navigationsleiste verdeckt.","iPhone & iPad (App Store): Neuer Einstellungsbildschirm in der App (Anzeige, Haptikstärke, Bildschirm anlassen, Abo & Käufe mit Wiederherstellen, Info). Das Panel folgt der in iOS gewählten Sprache (9 Sprachen)."],"fr":["Windows : TabDeck est maintenant sur le Microsoft Store — le bouton Windows du panneau et de l\'app Android l\'ouvre.","Linux : s\'il manque des paquets nécessaires à TabDeck (xdotool, ydotool, wl-clipboard, xdg-utils), TabDeck propose de les installer au démarrage ; saisissez le mot de passe administrateur et ils sont installés. Fonctionne sous X11 et Wayland avec apt, dnf, zypper et pacman.","Linux : si vous avez choisi « Plus tard », utilisez « Installer les paquets requis… » dans le menu de la zone de notification à tout moment. Après l\'installation, TabDeck se reconnecte et les avertissements comme « xdotool manquant » disparaissent.","Android : correction du panneau qui ajoutait un appareil portant le nom du téléphone alors qu\'aucun appareil Bluetooth n\'était connecté.","Android (Google Play) : correction du bouton « Gérer ou résilier l\'abonnement » qui affichait une longue phrase, et du haut et du bas de l\'écran masqués par les barres d\'état et de navigation sous Android 15 et versions ultérieures.","iPhone et iPad (App Store) : nouvel écran de réglages dans l\'app (affichage, intensité du retour haptique, écran toujours allumé, abonnement et achats avec restauration, à propos). Le panneau suit la langue choisie dans iOS (9 langues)."],"es":["Windows: TabDeck ya está en Microsoft Store — el botón Windows del panel y de la app de Android lo abre.","Linux: si faltan paquetes que TabDeck necesita (xdotool, ydotool, wl-clipboard, xdg-utils), TabDeck ofrece instalarlos al iniciar; introduzca la contraseña de administrador y se instalan. Funciona en X11 y Wayland con apt, dnf, zypper y pacman.","Linux: si eligió \\"Más tarde\\", use \\"Instalar paquetes necesarios…\\" en el menú de la bandeja en cualquier momento. Tras la instalación, TabDeck se vuelve a conectar y desaparecen avisos como \\"falta xdotool\\".","Android: se corrigió que el panel añadiera un dispositivo con el nombre del teléfono aunque no hubiera ningún dispositivo Bluetooth conectado.","Android (Google Play): se corrigió que el botón \\"Gestionar o cancelar la suscripción\\" mostrara una frase larga y que en Android 15 y posteriores las barras de estado y navegación taparan la parte superior e inferior de la pantalla.","iPhone y iPad (App Store): nueva pantalla de ajustes en la app (pantalla, intensidad háptica, mantener la pantalla encendida, suscripción y compras con restauración, información). El panel sigue el idioma elegido en iOS (9 idiomas)."],"pt-br":["Windows: o TabDeck agora está na Microsoft Store — o botão Windows do painel e do app Android abre a loja.","Linux: se faltarem pacotes de que o TabDeck precisa (xdotool, ydotool, wl-clipboard, xdg-utils), o TabDeck oferece instalá-los ao iniciar; digite a senha de administrador e eles são instalados. Funciona no X11 e no Wayland com apt, dnf, zypper e pacman.","Linux: se você escolheu \\"Depois\\", use \\"Instalar pacotes necessários…\\" no menu da bandeja a qualquer momento. Após a instalação, o TabDeck se reconecta e avisos como \\"xdotool ausente\\" desaparecem.","Android: corrigido o painel adicionar um dispositivo com o nome do celular mesmo sem nenhum dispositivo Bluetooth conectado.","Android (Google Play): corrigido o botão \\"Gerenciar ou cancelar assinatura\\" mostrando uma frase longa, e a parte de cima e de baixo da tela ficando cobertas pelas barras de status e navegação no Android 15 ou mais recente.","iPhone e iPad (App Store): nova tela de ajustes no app (tela, intensidade da vibração, manter a tela ligada, assinatura e compras com restauração, sobre). O painel segue o idioma escolhido no iOS (9 idiomas)."]},"0.3.24":{"ja":["Linux: アプリ内アップデートの後に再起動した TabDeck が次のアップデートをインストールできない問題（\\"pkexec must be setuid root\\"）を修正しました。","Linux: その状態でアップデートすると、エラーの代わりに対処方法（終了して再起動、またはターミナルで sudo apt install …）を表示します。"],"zh-cn":["Linux： 修复通过应用内更新重新启动后的 TabDeck 无法安装下一次更新的问题（\\"pkexec must be setuid root\\"）。","Linux： 在这种状态下更新时，会显示解决方法（退出后重新启动，或在终端运行 sudo apt install …），而不是直接报错。"],"zh-tw":["Linux： 修正透過應用程式內更新重新啟動後的 TabDeck 無法安裝下一次更新的問題（\\"pkexec must be setuid root\\"）。","Linux： 在這種狀態下更新時，會顯示解決方法（結束後重新啟動，或在終端機執行 sudo apt install …），而不是直接出錯。"],"de":["Linux: Behoben: Nachdem sich TabDeck nach einem In-App-Update selbst neu gestartet hatte, konnte es das nächste Update nicht installieren („pkexec must be setuid root“).","Linux: In diesem Zustand erklärt das Update jetzt, was zu tun ist (beenden und neu starten oder sudo apt install … im Terminal), statt fehlzuschlagen."],"fr":["Linux : correction de TabDeck qui ne pouvait pas installer la mise à jour suivante après s\'être relancé à la suite d\'une mise à jour intégrée (« pkexec must be setuid root »).","Linux : dans ce cas, la mise à jour indique maintenant quoi faire (quitter et relancer, ou sudo apt install … dans un terminal) au lieu d\'échouer."],"es":["Linux: se corrigió que TabDeck no pudiera instalar la siguiente actualización después de reiniciarse tras una actualización desde la app (\\"pkexec must be setuid root\\").","Linux: en ese caso, la actualización ahora explica qué hacer (cerrar y volver a abrir, o sudo apt install … en una terminal) en lugar de fallar."],"pt-br":["Linux: corrigido o TabDeck não conseguir instalar a próxima atualização depois de reiniciar sozinho após uma atualização pelo app (\\"pkexec must be setuid root\\").","Linux: nesse caso, a atualização agora explica o que fazer (fechar e abrir de novo, ou sudo apt install … no terminal) em vez de falhar."]},"0.3.23":{"ja":["Linux（Wayland）: deb でインストールすると、キーボード・マウス入力に必要な ydotool や wl-clipboard なども一緒にインストールされ、ログイン中のユーザーが入力デバイス（/dev/uinput）を使えるよう自動で設定されます。ydotoold サービスが動いていない場合は TabDeck が起動します。","Linux: アプリの自動アップデートも apt でインストールするため、必要なパッケージが一緒に入ります。","接続ウィンドウ: 「アドレスをコピー」の下に「Web ブラウザーからすぐに操作できます。または ストアで TabDeck アプリをインストールしてください。」を表示します。"],"zh-cn":["Linux（Wayland）： 通过 deb 安装时会一并安装键盘和鼠标输入所需的 ydotool、wl-clipboard 等，并自动让已登录用户可以使用输入设备（/dev/uinput）。如果 ydotoold 服务未运行，TabDeck 会自行启动它。","Linux： 应用自动更新也改为通过 apt 安装，所需软件包会一并安装。","连接窗口： “复制地址”下方新增提示：“可直接在网页浏览器中控制。或 从应用商店安装 TabDeck 应用。”"],"zh-tw":["Linux（Wayland）： 以 deb 安裝時會一併安裝鍵盤與滑鼠輸入所需的 ydotool、wl-clipboard 等，並自動讓已登入的使用者可以使用輸入裝置（/dev/uinput）。若 ydotoold 服務未執行，TabDeck 會自行啟動。","Linux： 應用程式自動更新也改用 apt 安裝，所需套件會一併安裝。","連線視窗： 「複製網址」下方新增提示：「可直接在網頁瀏覽器中控制。或 從應用程式商店安裝 TabDeck App。」"],"de":["Linux (Wayland): Bei der Installation per deb werden ydotool, wl-clipboard und die übrigen Werkzeuge für Tastatur- und Mauseingaben mitinstalliert, und der angemeldete Benutzer erhält Zugriff auf das Eingabegerät (/dev/uinput). Läuft der Dienst ydotoold nicht, startet TabDeck ihn selbst.","Linux: Automatische Updates werden jetzt über apt installiert, sodass benötigte Pakete mitkommen.","Verbindungsfenster: Unter „Adresse kopieren“: „Sie können direkt im Webbrowser steuern oder installieren Sie die TabDeck-App aus dem Store.“"],"fr":["Linux (Wayland) : l\'installation du paquet deb installe aussi ydotool, wl-clipboard et les autres outils nécessaires au clavier et à la souris, et donne à l\'utilisateur connecté l\'accès au périphérique d\'entrée (/dev/uinput). Si le service ydotoold n\'est pas lancé, TabDeck le démarre.","Linux : les mises à jour automatiques passent désormais par apt, ce qui installe aussi les paquets nécessaires.","Fenêtre de connexion : sous « Copier l\'adresse » : « Vous pouvez le contrôler directement depuis un navigateur web, ou installez l\'application TabDeck depuis le store. »"],"es":["Linux (Wayland): al instalar el deb también se instalan ydotool, wl-clipboard y las demás herramientas necesarias para el teclado y el ratón, y el usuario conectado obtiene acceso al dispositivo de entrada (/dev/uinput). Si el servicio ydotoold no está en marcha, TabDeck lo inicia.","Linux: las actualizaciones automáticas ahora se instalan con apt, así que se instalan también los paquetes necesarios.","Ventana de conexión: bajo «Copiar dirección»: «Puede controlarlo directamente desde un navegador web, o instale la app TabDeck desde la tienda»."],"pt-br":["Linux (Wayland): ao instalar o deb, o ydotool, o wl-clipboard e as demais ferramentas de teclado e mouse também são instalados, e o usuário conectado ganha acesso ao dispositivo de entrada (/dev/uinput). Se o serviço ydotoold não estiver rodando, o TabDeck o inicia.","Linux: as atualizações automáticas agora são instaladas pelo apt, trazendo junto os pacotes necessários.","Janela de conexão: abaixo de \\"Copiar endereço\\": \\"Você pode controlar direto pelo navegador, ou instale o app TabDeck pela loja.\\""]},"0.3.22":{"ja":["アップデート: デスクトップアプリは GitHub の最新リリースからアップデートを受け取るようになりました。設定のアップデートサーバー欄にリリースページのアドレス（…/releases/latest）を入れることもできます。","Linux: アプリアイコンが空の歯車で表示される問題を修正しました。複数サイズのアイコンを同梱し、実行中のウィンドウがアプリアイコンと結び付くようにしました。","Windows: ショートカットやタスクバーに Electron の既定アイコンが表示される問題を修正しました。実行ファイルに TabDeck のアイコンとバージョン情報が入ります。","接続ウィンドウ: 最大化ボタンをなくしました。最小化するとトレイ（メニューバー）に入ります。"],"zh-cn":["更新： 桌面应用现在从 GitHub 最新发布获取更新。也可以在设置的更新服务器栏中填入发布页面地址（…/releases/latest）。","Linux： 修复应用图标显示为空白齿轮的问题。现在包含多种尺寸的图标，运行中的窗口也能对应到应用图标。","Windows： 修复快捷方式和任务栏显示 Electron 默认图标的问题。程序文件现在带有 TabDeck 图标和版本信息。","连接窗口： 去掉了最大化按钮。最小化后会进入托盘（菜单栏）。"],"zh-tw":["更新： 桌面應用程式現在從 GitHub 最新版本取得更新。也可以在設定的更新伺服器欄位填入發行頁面網址（…/releases/latest）。","Linux： 修正應用程式圖示顯示為空白齒輪的問題。現在包含多種尺寸的圖示，執行中的視窗也能對應到應用程式圖示。","Windows： 修正捷徑與工作列顯示 Electron 預設圖示的問題。執行檔現在帶有 TabDeck 圖示與版本資訊。","連線視窗： 移除最大化按鈕。最小化後會進入系統匣（選單列）。"],"de":["Updates: Die Desktop-App bezieht Updates jetzt aus dem neuesten GitHub-Release. Im Feld „Update-Server“ der Einstellungen kann auch die Adresse der Release-Seite (…/releases/latest) stehen.","Linux: Das App-Symbol wurde als leeres Zahnrad angezeigt – behoben. Symbole in mehreren Größen sind enthalten, und laufende Fenster werden dem App-Symbol zugeordnet.","Windows: Verknüpfungen und Taskleiste zeigten das Standardsymbol von Electron – behoben. Die Programmdatei enthält jetzt das TabDeck-Symbol und die Versionsinformationen.","Verbindungsfenster: Keine Maximieren-Schaltfläche mehr. Beim Minimieren wandert es in den Infobereich (Menüleiste)."],"fr":["Mises à jour : l\'application de bureau se met désormais à jour depuis la dernière version publiée sur GitHub. Vous pouvez aussi coller l\'adresse de la page de version (…/releases/latest) dans le champ du serveur de mise à jour des réglages.","Linux : correction de l\'icône de l\'application affichée comme un engrenage vide. Des icônes de plusieurs tailles sont incluses et les fenêtres ouvertes sont associées à l\'icône de l\'application.","Windows : correction des raccourcis et de la barre des tâches qui affichaient l\'icône par défaut d\'Electron. Le fichier du programme contient maintenant l\'icône et les informations de version de TabDeck.","Fenêtre de connexion : plus de bouton Agrandir. La réduire l\'envoie dans la zone de notification (barre des menus)."],"es":["Actualizaciones: la app de escritorio ahora se actualiza desde la última versión publicada en GitHub. También puede pegar la dirección de la página de la versión (…/releases/latest) en el campo del servidor de actualizaciones de los ajustes.","Linux: se corrigió el icono de la app que aparecía como un engranaje vacío. Se incluyen iconos de varios tamaños y las ventanas abiertas se asocian al icono de la app.","Windows: se corrigió que los accesos directos y la barra de tareas mostraran el icono predeterminado de Electron. El archivo del programa ahora incluye el icono y la información de versión de TabDeck.","Ventana de conexión: ya no tiene botón de maximizar. Al minimizarla pasa a la bandeja (barra de menús)."],"pt-br":["Atualizações: o app para computador agora se atualiza pela versão mais recente no GitHub. Você também pode colar o endereço da página da versão (…/releases/latest) no campo do servidor de atualização nas configurações.","Linux: corrigido o ícone do app que aparecia como uma engrenagem vazia. Ícones em vários tamanhos foram incluídos e as janelas abertas agora são associadas ao ícone do app.","Windows: corrigido o ícone padrão do Electron nos atalhos e na barra de tarefas. O arquivo do programa agora traz o ícone e as informações de versão do TabDeck.","Janela de conexão: sem botão de maximizar. Ao minimizar, ela vai para a bandeja (barra de menus)."]},"0.3.21":{"ja":["デスクトップ: 接続用 QR コードの下に App Store と Google Play のボタンを追加しました。Google Play ボタンを押すと、スマートフォンで読み取ってインストールできる QR コードが表示されます。iOS アプリは準備中です。","Android: QR スキャンに必要なコンポーネントが端末にない場合、自動でダウンロードしてからスキャンをやり直します。","Android: パソコンと接続している間は通知を表示し、接続が切れないようにします。通知の「停止」ですぐに終了できます。","Android・iOS・Web パネル: 最初の画面（デバイスの追加）に Windows・macOS・Linux 版 TabDeck の入手ボタンを追加しました。"],"zh-cn":["桌面版： 连接二维码下方新增 App Store 和 Google Play 按钮。点击 Google Play 会显示可用手机扫描安装的二维码。iOS 应用正在准备中。","Android： 如果设备上缺少扫码组件，会自动下载后重新扫描。","Android： 与电脑连接期间显示通知，以保持连接不中断。可点击通知中的“停止”立即结束。","Android、iOS 和网页面板： 首屏（添加设备）新增获取 Windows、macOS、Linux 版 TabDeck 的按钮。"],"zh-tw":["桌面版： 連線 QR 碼下方新增 App Store 與 Google Play 按鈕。點選 Google Play 會顯示可用手機掃描安裝的 QR 碼。iOS 應用程式正在準備中。","Android： 若裝置上缺少掃描元件，會自動下載後重新掃描。","Android： 與電腦連線期間顯示通知，讓連線不中斷。可點選通知中的「停止」立即結束。","Android、iOS 與網頁面板： 首頁（新增裝置）新增取得 Windows、macOS、Linux 版 TabDeck 的按鈕。"],"de":["Desktop: Unter dem Verbindungs-QR-Code gibt es jetzt Schaltflächen für App Store und Google Play. Google Play zeigt einen QR-Code, den Sie mit dem Handy scannen, um die App zu installieren. Die iOS-App folgt in Kürze.","Android: Fehlt die QR-Scanner-Komponente auf dem Gerät, lädt TabDeck sie herunter und startet den Scan erneut.","Android: Während eine Verbindung zum Computer besteht, wird eine Benachrichtigung angezeigt, damit die Verbindung bestehen bleibt. Mit „Beenden“ in der Benachrichtigung lässt sie sich sofort trennen.","Android, iOS und Web-Panel: Der erste Bildschirm (Gerät hinzufügen) enthält jetzt Schaltflächen für TabDeck für Windows, macOS und Linux."],"fr":["Bureau : boutons App Store et Google Play sous le QR code de connexion. Google Play affiche un QR code à scanner avec votre téléphone pour installer l\'application. L\'application iOS arrive bientôt.","Android : si le composant de lecture de QR code manque sur l\'appareil, TabDeck le télécharge puis relance la lecture.","Android : une notification s\'affiche tant que l\'appareil est connecté à un ordinateur, pour que la connexion reste active. Touchez « Arrêter » dans la notification pour y mettre fin.","Android, iOS et panneau web : le premier écran (Ajouter un appareil) propose des boutons pour obtenir TabDeck pour Windows, macOS et Linux."],"es":["Escritorio: botones de App Store y Google Play bajo el código QR de conexión. Google Play muestra un código QR que puede escanear con el teléfono para instalar la app. La app para iOS llegará pronto.","Android: si falta en el dispositivo el componente para escanear códigos QR, TabDeck lo descarga y vuelve a escanear.","Android: se muestra una notificación mientras está conectado a un ordenador para que la conexión no se corte. Toque «Detener» en la notificación para terminarla.","Android, iOS y panel web: la primera pantalla (Añadir dispositivo) incluye botones para obtener TabDeck para Windows, macOS y Linux."],"pt-br":["Desktop: botões da App Store e do Google Play abaixo do QR code de conexão. O Google Play mostra um QR code que você pode escanear com o celular para instalar o app. O app para iOS chegará em breve.","Android: se o componente de leitura de QR code estiver ausente no aparelho, o TabDeck o baixa e tenta escanear de novo.","Android: uma notificação é exibida enquanto o aparelho está conectado a um computador, para manter a conexão ativa. Toque em \\"Parar\\" na notificação para encerrá-la.","Android, iOS e painel web: a primeira tela (Adicionar dispositivo) agora tem botões para obter o TabDeck para Windows, macOS e Linux."]}}');const i=[{version:"0.3.25",date:"2026-11-19",ko:["Windows: Microsoft Store에 정식 등록되었습니다.","Linux: 필요한 패키지가 없으면 시작할 때 바로 설치해 줍니다(apt·dnf·zypper·pacman).","Android: 블루투스 기기가 없는데 패널에 기기가 추가되던 문제, Android 15 이상에서 화면 위아래가 가리던 문제를 고쳤습니다."],en:["Windows: TabDeck is now on the Microsoft Store.","Linux: Missing packages are offered for install at startup (apt, dnf, zypper, pacman).","Android: Fixed a phantom Bluetooth device in the panel and the screen edges being covered on Android 15 and later."]},{version:"0.3.24",date:"2026-11-18",ko:["Linux: 앱 안에서 업데이트한 뒤 다음 업데이트가 설치되지 않던 문제를 고쳤습니다."],en:["Linux: Fixed the next update failing to install after an in-app update."]},{version:"0.3.23",date:"2026-11-18",ko:["Linux(Wayland): deb로 설치하면 키보드·마우스 입력에 필요한 도구와 권한이 자동으로 설정됩니다.","연결 창: 웹 브라우저에서 바로 제어할 수 있다는 안내를 넣었습니다."],en:["Linux (Wayland): Installing the deb now sets up the tools and permissions needed for keyboard and mouse input.","Connection window: Notes that you can control the computer right away from a web browser."]},{version:"0.3.22",date:"2026-11-18",ko:["데스크톱 앱이 GitHub 최신 릴리스에서 업데이트를 받습니다.","Windows·Linux: 앱 아이콘이 기본 아이콘으로 보이던 문제를 고쳤습니다."],en:["The desktop app now updates from the latest GitHub release.","Windows & Linux: Fixed the app showing a default icon."]},{version:"0.3.21",date:"2026-11-18",ko:["데스크톱: 연결 QR 코드 아래에 스토어 설치 버튼과 설치용 QR 코드를 넣었습니다.","Android: 연결 중에는 알림을 띄워 연결이 끊기지 않게 합니다."],en:["Desktop: Store buttons and an install QR code under the connection QR code.","Android: A notification keeps the connection alive while connected."]}];function t(e,a){if("ko"===a||"en"===a)return e[a];const n=o[e.version]&&o[e.version][a];return n&&n.length?n:e.en}}}]);